import{indieIdeas,populateIndiePreset,tone}from'./indie-presets.js';
export const templates={blank:'Empty scene',platformer:'Platformer',rhythm:'Rhythm runner',topdown:'Top-down adventure',space:'Space shooter',puzzle:'Coin maze',runner:'Auto runner',...indieIdeas};
export const objectTypes=['player','platform','coin','hazard','enemy','trigger','camera','flag','gear','sprite'];
export function makeObject(type,x=160,y=160){
 const sizes={player:[38,44],platform:[192,32],coin:[32,32],hazard:[96,32],enemy:[40,40],trigger:[96,96],camera:[96,64],flag:[48,96],gear:[96,96],sprite:[64,24]};
 if(!sizes[type])throw Error('Unknown object type');
 return {id:crypto.randomUUID(),name:type[0].toUpperCase()+type.slice(1),type,x,y,w:sizes[type][0],h:sizes[type][1],color:{player:'#d2e8f8',platform:'#78c929',coin:'#ffcf26',hazard:'#d9e7ed',enemy:'#ed5266',trigger:'#a680dc',camera:'#8fa0b1',flag:'#ef5559',gear:'#91a6be',sprite:'#b48ddd'}[type],physics:!['camera','sprite'].includes(type),body:['player','enemy','gear'].includes(type)?'dynamic':type==='platform'?'static':'trigger',gravity:1,friction:.5,bounce:0,events:[],...(type==='gear'?{draggable:false,pinned:true,rotation:0,motor:false,motorRPM:10}:{})};
}
export function createProject(name,template='blank'){
 if(!name.trim()||name.length>80||!Object.hasOwn(templates,template))throw Error('Enter a project name and choose a valid template.');
 const objects=[];
 const add=(type,x,y,w,h,label)=>{const o=makeObject(type,x,y);if(w)o.w=w;if(h)o.h=h;if(label)o.name=label;objects.push(o);return o};
 if(['platformer','rhythm','runner'].includes(template)){
  add('player',150,354);add('platform',0,400,288,160,'Start platform');add('platform',288,512,288,48,'Lower platform');add('platform',576,432,96,128,'Step');add('platform',672,320,288,240,'Goal platform');add('hazard',304,480,256,32,'Spikes');
  for(let i=0;i<(template==='rhythm'?6:3);i++){const o=add('coin',416+i*88,template==='rhythm'?300:300-i*32);o.name=`Coin ${i+1}`;if(i>0)o.events=[{id:crypto.randomUUID(),condition:'touch',action:'score',value:1}]}
  add('flag',800,224,48,96,'Checkpoint flag');
 }
 if(['topdown','puzzle','space'].includes(template)){
  add('player',80,260);if(template!=='space'){add('platform',0,0,960,32,'Top boundary');add('platform',0,508,960,32,'Bottom boundary');add('platform',300,0,32,240,'Maze wall');add('platform',600,270,32,240,'Maze wall 2')}
  for(let i=0;i<5;i++){const o=add('coin',200+i*140,160+(i%2)*160);o.name=`Coin ${i+1}`;o.events=[{id:crypto.randomUUID(),condition:'touch',action:'score',value:1}]}
  for(let i=0;i<(template==='space'?5:2);i++)add('enemy',370+i*100,200+(i%2)*100);
  add('flag',860,100,48,96,'Goal');
 }
 const project={format:'playform',version:1,id:crypto.randomUUID(),name:name.trim(),template,updated:Date.now(),objects,gravity:['topdown','space','puzzle'].includes(template)?0:1,variables:{Score:0,Health:3},sceneName:'MainScene',description:'',assets:[]};
 if(['rhythm','runner'].includes(template)){project.objects=[];const actor=makeObject('player',140,396);project.objects.push(actor);const floor=makeObject('platform',0,440);floor.w=960;floor.h=100;floor.name='Endless track';project.objects.push(floor);const speed=template==='rhythm'?220:180;project.autoRun={enabled:true,speed};const loop=o=>o.events.push({id:crypto.randomUUID(),condition:'frame',action:'loopmove',axis:'x',direction:-1,movementMode:'wrap',value:speed});for(let i=0;i<2;i++){const hazard=makeObject('hazard',700+i*480,408);hazard.w=32;hazard.h=32;hazard.name=`Obstacle ${i+1}`;loop(hazard);project.objects.push(hazard)}for(let i=0;i<6;i++){const pickup=makeObject('coin',380+i*150,350);pickup.events=[{id:crypto.randomUUID(),condition:'touch',action:'score',value:1}];loop(pickup);project.objects.push(pickup)}if(template==='rhythm'){const beat=tone('Metronome',660),clock=makeObject('trigger',0,0);clock.name='Beat clock';clock.events=[{id:crypto.randomUUID(),condition:'timer',action:'sound',value:1,interval:.5,repeat:true,soundId:beat.id}];project.objects.push(clock);project.sounds=[beat];project.bpm=120}project.instructions='Runs automatically. Press Space or tap Jump to clear obstacles. The track repeats forever.'}
 return Object.hasOwn(indieIdeas,template)?populateIndiePreset(project,makeObject):project;
}
export function validateProject(p){
 if(!p||p.format!=='playform'||p.version!==1||typeof p.name!=='string'||!p.name.trim()||p.name.length>80||!Object.hasOwn(templates,p.template)||!Array.isArray(p.objects)||p.objects.length>10000)throw Error('This is not a supported Playform project.');
 if(p.inputs!==undefined&&p.inputs!==null&&(typeof p.inputs!=='object'||Object.entries(p.inputs).some(([k,v])=>!['left','right','up','down','jump','shoot'].includes(k)||typeof v!=='string'||!/^[A-Za-z0-9]{1,32}$/.test(v))))throw Error('Project contains invalid input bindings.');
 const isImage=value=>typeof value==='string'&&value.length<=3000000&&/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(value);
 if(p.assets!==undefined&&(!Array.isArray(p.assets)||p.assets.length>200||p.assets.some(a=>!a||typeof a.id!=='string'||typeof a.name!=='string'||a.name.length>200||!['sprites','hazards','collectibles','environment'].includes(a.category)||!isImage(a.data))))throw Error('Project contains invalid imported assets.');
 if(p.backgroundAsset!=null&&!isImage(p.backgroundAsset))throw Error('Project contains an invalid background image.');
 if(p.titleScreen!=null){const t=p.titleScreen;if(typeof t!=='object'||(t.title!==undefined&&(typeof t.title!=='string'||t.title.length>80))||(t.subtitle!==undefined&&(typeof t.subtitle!=='string'||t.subtitle.length>160))||(t.playLabel!==undefined&&(typeof t.playLabel!=='string'||t.playLabel.length>24))||(t.accent!==undefined&&!/^#[\da-f]{6}$/i.test(t.accent))||(t.logo!==undefined&&!isImage(t.logo))||(t.artwork!==undefined&&!isImage(t.artwork)))throw Error('Project contains invalid title-screen settings.');}
 const ids=new Set();for(const o of p.objects){if(!o||typeof o.id!=='string'||ids.has(o.id)||typeof o.name!=='string'||o.name.length>200||!objectTypes.includes(o.type)||!['x','y','w','h'].every(k=>Number.isFinite(o[k])&&Math.abs(o[k])<100000)||o.w<=0||o.h<=0||!/^#[\da-f]{6}$/i.test(o.color))throw Error('Project contains invalid scene objects.');ids.add(o.id);if(o.spriteLayers!==undefined&&(!o.spriteLayers||![16,32,64].includes(o.spriteLayers.size)||!Array.isArray(o.spriteLayers.layers)||!o.spriteLayers.layers.length||o.spriteLayers.layers.length>100||o.spriteLayers.layers.some(l=>!l||typeof l.name!=='string'||!Array.isArray(l.pixels)||l.pixels.length!==o.spriteLayers.size**2)))throw Error('Project contains invalid sprite layers.');if(o.asset!==undefined&&!isImage(o.asset))throw Error('Project contains an invalid sprite.');if(o.animation!==undefined){if(!o.animation||!o.animation.states||typeof o.animation.states!=='object'||Object.keys(o.animation.states).length>40)throw Error('Project contains invalid animations.');for(const state of Object.values(o.animation.states))if(!state||!Array.isArray(state.frames)||state.frames.length>200||!state.frames.every(isImage)||!Number.isFinite(state.fps)||state.fps<1||state.fps>60)throw Error('Project contains invalid animation frames.');}if(o.events!==undefined&&(!Array.isArray(o.events)||o.events.some(e=>!e||!['score','damage','checkpoint','sound','drag','moveplatform','attach','facepointer','shoot','toggle','show','hide','setgravity','addvariable','setvariable','finish','loopmove'].includes(e.action)||!['touch','start','pointerdown','gearturn','frame','timer','input','variable','drop','projectilehit'].includes(e.condition)||!Number.isFinite(e.value)||Math.abs(e.value)>1e6)))throw Error('Project contains invalid events.');for(const field of ['rotation','motorRPM'])if(o[field]!==undefined&&(!Number.isFinite(o[field])||Math.abs(o[field])>100000))throw Error('Project contains an invalid rotation or motor value.');for(const k of ['bounce','friction'])if(o[k]!==undefined&&(!Number.isFinite(o[k])||o[k]<0||o[k]>1))throw Error('Project contains invalid physics settings.');}
 if(p.sounds!==undefined&&(!Array.isArray(p.sounds)||p.sounds.length>100||p.sounds.some(s=>!s||typeof s.id!=='string'||typeof s.name!=='string'||s.name.length>80||typeof s.data!=='string'||s.data.length>2000000||!/^data:audio\/wav;base64,[A-Za-z0-9+/=]+$/.test(s.data))))throw Error('Project contains invalid audio.');for(const key of ['width','height'])if(p[key]!==undefined&&(!Number.isInteger(p[key])||p[key]<160||p[key]>4096))throw Error('Project contains an invalid game size.');
 return {...p,id:typeof p.id==='string'?p.id:crypto.randomUUID(),updated:Number.isFinite(p.updated)?p.updated:Date.now(),gravity:Number.isFinite(p.gravity)?Math.max(0,Math.min(10,p.gravity)):1,variables:p.variables&&typeof p.variables==='object'&&!Array.isArray(p.variables)?Object.fromEntries(Object.entries(p.variables).filter(([k,v])=>k.length<=40&&Number.isFinite(v))):{Score:0,Health:3}};
}
